/**
 * @fileoverview Warns when a call to the override method is made and thus should be reviewed to determine the ExtJS upgrade impact.
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/override-method-call'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester();
ruleTester.run('override-method-call', rule, {

    valid: [
        {
            code: `
                Ext.define('MyCustomPanel', {
                    extend: 'Ext.panel.Panel',
                    setTitle: function () {
                        return this.callParent(arguments);
                    } 
                });
            `
        }
    ],

    invalid: [
        {
            code: `
                Ext.override(panel, {
                    initComponent: function () {
                        this.callParent();
                    }
                });
            `,
            errors: [{
                message: 'Call to \'Ext.override()\' method found'
            }]
        },
        {
            code: 'this.override();',
            errors: [{
                message: 'Call to \'this.override()\' method found'
            }]
        },
        {
            code: `
                Ext.define('MyCustomClass', {
                    extend: 'Ext.Component',
                    constructor: function () {
                        var me = this;
                        me.override({
                            alignTo: function () {}
                        });
                        me.callParent();
                    }
                });
            `,
            errors: [{
                message: 'Call to \'me.override()\' method found'
            }]
        }
    ]
});
